[CmdletBinding(SupportsShouldProcess)]param([Parameter(Mandatory)][string]$ApiUrl,[Parameter(Mandatory)][string]$Manifest,[switch]$AddSemanticBreadcrumbs,[string]$BreadcrumbProperty='Has parent page')
$ErrorActionPreference='Stop'; $m=Get-Content $Manifest -Raw|ConvertFrom-Json
function Api($p){$p.format='json';Invoke-RestMethod "$ApiUrl?$(( $p.GetEnumerator()|%{'{0}={1}'-f $_.Key,[uri]::EscapeDataString([string]$_.Value)})-join'&')"}
$pages=@(Api @{action='query';list='allpages';aplimit=1}.query.allpages); if($pages.Count){throw 'Target wiki is not blank; refusing to overwrite pages.'}
$map=@{};foreach($x in @($m.page_mapping)){$map[[string]$x.pageid]=$x};$ns=@($m.namespace_mapping|? create_if_missing);if($ns){$cfg=@('// Generated namespace declarations')+@($ns|%{'$wgExtraNamespaces['+$_.destination_id+'] = '''+$_.destination_name+''';'});$cfg|Set-Content (Join-Path (Split-Path $Manifest) 'namespace-settings.php') -Encoding utf8;Write-Host 'Created namespace-settings.php; apply it before importing pages.'}
$t=(Api @{action='query';meta='tokens';type='csrf'}).query.tokens.csrftoken
foreach($p in $m.pages){$d=$map[[string]$p.pageid];$title=if($d -and ($d.destination_title -or $d.title)){if($d.destination_title){$d.destination_title}else{$d.title}}else{$p.title};$parent='';if($d.parent_path){$parent="$($d.parent_path.Trim('/'))";$title="$parent/$title"};$namespace=if($d.destination_namespace){$d.destination_namespace}elseif($d.namespace){($m.namespace_mapping|? destination_id -eq $d.namespace|select -First 1).destination_name};if($namespace){$title="$namespace`:$title"};$text=$p.source;if($AddSemanticBreadcrumbs -and $parent){$parentTitle=if($namespace){"$namespace`:$parent"}{$parent};$text="[[${BreadcrumbProperty}::$parentTitle]]`n`n$text"};if($PSCmdlet.ShouldProcess($title,'Create page')){Invoke-RestMethod $ApiUrl -Method Post -Body @{action='edit';title=$title;text=$text;token=$t;format='json'}|Out-Null}}
Write-Host "Created $($m.pages.Count) pages. Files remain available from manifest assets for upload."
